class CanarioCampo {
  final String visible;
  final String olvidado;
  const CanarioCampo(this.visible, this.olvidado);
  Map<String, Object?> toJson() => {'visible': visible};
  factory CanarioCampo.fromJson(Map<String, Object?> json) =>
      CanarioCampo(json['visible']! as String, '');
}

abstract interface class CanarioPuerto {
  void hacerAlgo();
}

class CanarioOpaco {
  final String campo;
  const CanarioOpaco(this.campo);
}

class CanarioColeccion {
  final List<String> items;
  const CanarioColeccion(this.items);
  Map<String, Object?> toJson() => {'items': items};
  factory CanarioColeccion.fromJson(Map<String, Object?> json) =>
      CanarioColeccion(List<String>.from(json['items']! as List<Object?>));
}
